55	String DataTypeAggregateFunction::getNameImpl(bool with_version) const
56	{
57	    WriteBufferFromOwnString stream;
58	    stream << "AggregateFunction(";
59	
60	    /// If aggregate function does not support versioning its version is 0 and is not printed.
61	    auto data_type_version = getVersion();
62	    if (with_version && data_type_version)
63	        stream << data_type_version << ", ";
64	    stream << function->getName();
65	
66	    if (!parameters.empty())
67	    {
68	        stream << '(';
69	        for (size_t i = 0; i < parameters.size(); ++i)
70	        {
71	            if (i)
72	                stream << ", ";
73	            stream << applyVisitor(FieldVisitorToString(), parameters[i]);
74	        }
75	        stream << ')';
76	    }
77	
78	    for (const auto & argument_type : argument_types)
79	        stream << ", " << argument_type->getName();
80	
81	    stream << ')';
82	    return stream.str();
83	}
