132	static DataTypePtr create(const ASTPtr & arguments)
133	{
134	    String function_name;
135	    AggregateFunctionPtr function;
136	    DataTypes argument_types;
137	    Array params_row;
138	    std::optional<size_t> version;
139	
140	    if (!arguments || arguments->children.empty())
141	        throw Exception("Data type AggregateFunction requires parameters: "
142	            "version(optionally), name of aggregate function and list of data types for arguments", ErrorCodes::NUMBER_OF_ARGUMENTS_DOESNT_MATCH);
143	
144	    ASTPtr data_type_ast = arguments->children[0];
145	    size_t argument_types_start_idx = 1;
146	
147	    /* If aggregate function definition doesn't have version, it will have in AST children args [ASTFunction, types...] - in case
148	     * it is parametric, or [ASTIdentifier, types...] - otherwise. If aggregate function has version in AST, then it will be:
149	     * [ASTLiteral, ASTFunction (or ASTIdentifier), types...].
150	     */
151	    if (auto * version_ast = arguments->children[0]->as<ASTLiteral>())
152	    {
153	        if (arguments->children.size() < 2)
154	            throw Exception(ErrorCodes::NUMBER_OF_ARGUMENTS_DOESNT_MATCH,
155	                "Data type AggregateFunction has version, but it requires at least one more parameter - name of aggregate function");
156	        version = version_ast->value.safeGet<UInt64>();
157	        data_type_ast = arguments->children[1];
158	        argument_types_start_idx = 2;
159	    }
160	
161	    if (const auto * parametric = data_type_ast->as<ASTFunction>())
162	    {
163	        if (parametric->parameters)
164	            throw Exception("Unexpected level of parameters to aggregate function", ErrorCodes::SYNTAX_ERROR);
165	
166	        function_name = parametric->name;
167	
168	        if (parametric->arguments)
169	        {
170	            const ASTs & parameters = parametric->arguments->children;
171	            params_row.resize(parameters.size());
172	
173	            for (size_t i = 0; i < parameters.size(); ++i)
174	            {
175	                const auto * literal = parameters[i]->as<ASTLiteral>();
176	                if (!literal)
177	                    throw Exception(
178	                        ErrorCodes::PARAMETERS_TO_AGGREGATE_FUNCTIONS_MUST_BE_LITERALS,
179	                        "Parameters to aggregate functions must be literals. "
180	                        "Got parameter '{}' for function '{}'",
181	                        parameters[i]->formatForErrorMessage(), function_name);
182	
183	                params_row[i] = literal->value;
184	            }
185	        }
186	    }
187	    else if (auto opt_name = tryGetIdentifierName(data_type_ast))
188	    {
189	        function_name = *opt_name;
190	    }
191	    else if (data_type_ast->as<ASTLiteral>())
192	    {
193	        throw Exception("Aggregate function name for data type AggregateFunction must be passed as identifier (without quotes) or function",
194	            ErrorCodes::BAD_ARGUMENTS);
195	    }
196	    else
197	        throw Exception("Unexpected AST element passed as aggregate function name for data type AggregateFunction. Must be identifier or function.",
198	            ErrorCodes::BAD_ARGUMENTS);
199	
200	    for (size_t i = argument_types_start_idx; i < arguments->children.size(); ++i)
201	        argument_types.push_back(DataTypeFactory::instance().get(arguments->children[i]));
202	
203	    if (function_name.empty())
204	        throw Exception("Logical error: empty name of aggregate function passed", ErrorCodes::LOGICAL_ERROR);
205	
206	    AggregateFunctionProperties properties;
207	    function = AggregateFunctionFactory::instance().get(function_name, argument_types, params_row, properties);
208	    return std::make_shared<DataTypeAggregateFunction>(function, argument_types, params_row, version);
209	}
